package mediakernel

import (
	"encoding/binary"
	"math/rand"
)

// CorruptMode selects the self-contained damage applied to a fixture.
type CorruptMode string

const (
	CorruptNone            CorruptMode = ""
	CorruptTruncated       CorruptMode = "truncated"
	CorruptInvalidDuration CorruptMode = "invalid-duration"
	CorruptSequence        CorruptMode = "bad-sequence"
)

// FixtureSpec fully determines a generated byte stream, so two runs with the
// same spec produce bit-identical fixtures (used by repeat-run verification).
type FixtureSpec struct {
	Seed        int64       `json:"seed"`
	PacketCount int         `json:"packet_count"`
	Corrupt     CorruptMode `json:"corrupt"`
}

// Fixture is one generated packet stream plus its design-time expectations.
type Fixture struct {
	Spec               FixtureSpec `json:"spec"`
	Data               []byte      `json:"-"`
	WrittenFrames      int         `json:"written_frames"`
	DesignedLosses     int         `json:"designed_losses"`
	DesignedDuplicates int         `json:"designed_duplicates"`
	DesignedWraps      int         `json:"designed_wraps"`
}

// DefaultFixturePacketCount is the number of unique packets in a demo stream.
const DefaultFixturePacketCount = 24

// fixtureStartSeq sits close to the 16-bit boundary so normal demo streams
// exercise RTP sequence wraparound deterministically.
const fixtureStartSeq = uint16(65530)

// GenerateFixture builds the length-prefixed RTP packet stream for spec. The
// stream deliberately contains:
//
//   - packet loss: every 7th step skips a sequence number without writing it;
//   - duplicates: every 11th step re-writes the previous frame with same seq;
//   - wraparound: sequence numbers start at 65530 and cross 65535 -> 0;
//   - mixed Opus/AAC frames with legal but variable per-packet durations.
//
// Corruption, when requested, is applied to one interior frame.
func GenerateFixture(spec FixtureSpec) (*Fixture, error) {
	if spec.PacketCount <= 0 {
		spec.PacketCount = DefaultFixturePacketCount
	}
	rng := rand.New(rand.NewSource(spec.Seed))
	opus := []uint32{120, 240, 480, 960, 1920}
	aac := []uint32{960, 1024}

	var frames []fixtureFrame
	fx := &Fixture{Spec: spec}
	seq := fixtureStartSeq
	for i := 0; i < spec.PacketCount; i++ {
		// Designed loss: advance the sequence counter without emitting a frame.
		if i > 0 && i%7 == 3 {
			seq++
			fx.DesignedLosses++
		}
		codec := CodecOpus
		var samples uint32
		if i%4 == 0 {
			codec = CodecAAC
			samples = aac[rng.Intn(len(aac))]
		} else {
			samples = opus[rng.Intn(len(opus))]
		}
		payload := make([]byte, 20+rng.Intn(40))
		if _, err := rng.Read(payload); err != nil {
			return nil, NewError(PhaseParse, -1, "fixture rng failed").WithCause(err)
		}
		frames = append(frames, fixtureFrame{seq: seq, codec: codec, samples: samples, payload: payload})
		fx.WrittenFrames++
		// Designed duplicate: re-emit the same sequence before advancing.
		if i > 0 && i%11 == 5 {
			frames = append(frames, frames[len(frames)-1])
			fx.DesignedDuplicates++
		}
		// Count boundary crossings the sequence stream will observe.
		next := seq + 1
		if next < seq {
			fx.DesignedWraps++
		}
		seq = next
	}

	if err := applyCorruption(spec.Corrupt, frames); err != nil {
		return nil, err
	}

	var data []byte
	for _, fr := range frames {
		b, err := BuildFramedPacket(fr.seq, fr.codec, fr.samples, fr.payload, fr.flags)
		if err != nil {
			return nil, err
		}
		data = append(data, b...)
	}
	fx.Data = data
	return fx, nil
}

// fixtureFrame is one frame pending serialization.
type fixtureFrame struct {
	seq     uint16
	codec   Codec
	samples uint32
	payload []byte
	flags   uint8
}

// applyCorruption mutates one interior frame to create a locatable failure.
func applyCorruption(mode CorruptMode, frames []fixtureFrame) error {
	if mode == CorruptNone || len(frames) < 4 {
		return nil
	}
	k := len(frames) / 2
	switch mode {
	case CorruptInvalidDuration:
		frames[k].samples = 500 // legal for neither Opus nor AAC
	case CorruptSequence:
		// An unseen sequence number behind the high-water mark: the gap
		// tracker rejects it as a backwards sequence anomaly.
		frames[k].seq = fixtureStartSeq - 100
	case CorruptTruncated:
		// Handled at the byte-stream level by the caller via TruncateFrame.
	default:
		return NewError(PhaseParse, -1, "unknown corrupt mode: "+string(mode))
	}
	return nil
}

// TruncateFrame cuts tail bytes off the interior frame while leaving its
// 2-byte length prefix claiming the original size, producing a "truncated
// packet body" error at that frame's byte offset.
func TruncateFrame(data []byte) []byte {
	// Walk frames to find an interior one, then remove its last few bytes.
	offset := 0
	frameIdx := 0
	var cutStart int
	for offset+2 <= len(data) {
		frameLen := int(binary.BigEndian.Uint16(data[offset : offset+2]))
		frameIdx++
		next := offset + 2 + frameLen
		if frameIdx == 2 && next <= len(data) {
			cutStart = next - 4 // trim 4 payload bytes from this frame
		}
		offset = next
		if offset >= len(data) {
			break
		}
	}
	if cutStart == 0 || cutStart >= len(data) {
		return data
	}
	return append(append([]byte(nil), data[:cutStart]...), data[cutStart+4:]...)
}
